const body = $json.body || {};
const required = (name) => { const value = String(body[name] ?? '').trim(); if (!value) throw new Error('Missing ' + name); return value; };
const action = required('action');
const actorEmail = required('actor_email').toLowerCase();
if (!/^[^\s@]+@apexdp\.com$/i.test(actorEmail)) throw new Error('Administrator identity must be an Apex Workspace account.');
const idempotencyKey = required('idempotency_key');
if (!/^[A-Za-z0-9_-]{16,100}$/.test(idempotencyKey)) throw new Error('Invalid idempotency key.');

if (action === 'approve_for_doctor') {
  const reason = required('reason');
  if (reason.length < 12 || reason.length > 2000) throw new Error('Approval evidence must be 12–2000 characters.');
  const expectedVersion = Number(body.expected_version);
  if (!Number.isInteger(expectedVersion) || expectedVersion < 1) throw new Error('A valid expected article version is required.');
  return [{ json: { action, actor_email: actorEmail, idempotency_key: idempotencyKey, article_id: required('article_id'), campaign_id: required('campaign_id'), doctor_id: required('doctor_id'), expected_status: required('expected_status'), expected_version: expectedVersion, reason } }];
}

if (action === 'launch_campaign') {
  const audience = required('audience');
  if (!['Test users only', 'Presentation preview'].includes(audience)) throw new Error('Unsupported campaign audience.');

  const expectedConfirmation = audience === 'Presentation preview' ? 'SEND PREVIEW INVITATIONS' : 'SEND TEST INVITATIONS';
  if (required('launch_confirmation') !== expectedConfirmation) throw new Error('Campaign confirmation phrase did not match.');

  const allowedSourceTypes = new Set(['Apex-owned or commissioned', 'Licensed stock', 'AI-generated with approved terms']);
  const topics = Array.isArray(body.topics) ? body.topics.map((topic, index) => {
    const number = index + 1;
    const title = String(topic?.title || '').trim();
    const sourceUrl = String(topic?.featured_image_source_url || '').trim();
    const altText = String(topic?.featured_image_alt_text || '').trim();
    const sourceType = String(topic?.featured_image_source_type || '').trim();
    const rightsReference = String(topic?.featured_image_rights_reference || '').trim();
    if (!title) throw new Error('Topic ' + number + ' title is required.');
    if (!sourceUrl.startsWith('https://apexparent.hostmanpowered.com/wp-content/uploads/')) throw new Error('Topic ' + number + ' featured image must use the direct Apex Parent Media Library file URL.');
    if (altText.length < 8) throw new Error('Topic ' + number + ' needs useful featured image alt text.');
    if (!allowedSourceTypes.has(sourceType)) throw new Error('Topic ' + number + ' image source type is not allowed.');
    if (!rightsReference) throw new Error('Topic ' + number + ' image rights or source reference is required.');
    return { title, featured_image_source_url: sourceUrl, featured_image_alt_text: altText, featured_image_source_type: sourceType, featured_image_rights_reference: rightsReference };
  }) : [];

  const campaignName = required('campaign_name');
  const month = required('campaign_month');
  if (!/^\d{4}-\d{2}$/.test(month) || topics.length !== 3 || new Set(topics.map((topic) => topic.title.toLowerCase())).size !== 3) {
    throw new Error('Campaign month and three distinct topics with complete image records are required.');
  }

  const invitationSendAt = new Date(required('invitation_send_at'));
  if (Number.isNaN(invitationSendAt.getTime())) throw new Error('Invalid invitation send time.');
  const now = Date.now();
  if (invitationSendAt.getTime() < now - 2 * 60 * 1000) throw new Error('Invitation send time is too far in the past.');
  if (invitationSendAt.getTime() > now + 90 * 24 * 60 * 60 * 1000) throw new Error('Invitation send time must be within 90 days.');

  const slug = campaignName.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '').slice(0, 48);
  if (!slug) throw new Error('Campaign name needs letters or numbers.');

  let practiceId = '';
  let doctorIds = [];
  let recipientEmails = [];
  let previewOnly = false;

  if (audience === 'Test users only') {
    practiceId = required('practice_id');
    if (practiceId !== 'practice_test_001') throw new Error('Only the verified TEST001 practice is enabled for the full pipeline.');
    doctorIds = Array.isArray(body.doctor_ids) ? [...new Set(body.doctor_ids.map((id) => String(id).trim()).filter(Boolean))] : [];
    if (!doctorIds.length || doctorIds.length > 10) throw new Error('Select 1–10 TEST001 recipients.');
  } else {
    previewOnly = true;
    recipientEmails = Array.isArray(body.recipient_emails) ? [...new Set(body.recipient_emails.map((email) => String(email).trim().toLowerCase()).filter(Boolean))] : [];
    if (!recipientEmails.length || recipientEmails.length > 50) throw new Error('Presentation preview requires 1–50 recipient work emails.');
    if (recipientEmails.some((email) => !/^[^\s@]+@apexdp\.com$/i.test(email))) throw new Error('Presentation preview recipients must use Apex Workspace email addresses.');
  }

  const campaignPrefix = previewOnly ? 'campaign_preview_' : 'campaign_test_';
  const campaignId = campaignPrefix + month.replace('-', '') + '_' + slug;
  return [{ json: {
    action,
    audience,
    preview_only: previewOnly,
    actor_email: actorEmail,
    idempotency_key: idempotencyKey,
    campaign_id: campaignId,
    campaign_name: campaignName,
    campaign_month: month + '-01',
    invitation_send_at: invitationSendAt.toISOString(),
    browser_timezone: String(body.browser_timezone || '').trim(),
    practice_id: practiceId,
    topics_json: JSON.stringify(topics),
    doctor_ids_json: JSON.stringify(doctorIds),
    recipient_emails_json: JSON.stringify(recipientEmails),
  } }];
}

throw new Error('Unsupported administrative action.');

